import{_ as e,o as l,c as a,a0 as d}from"./chunks/framework.DqMqoJl9.js";const f=JSON.parse('{"title":"07 目标超导搜索策略","description":"","frontmatter":{},"headers":[],"relativePath":"D041_目标超导搜索策略.md","filePath":"D041_目标超导搜索策略.md"}'),r={name:"D041_目标超导搜索策略.md"};function n(s,t,o,i,_,g){return l(),a("div",null,[...t[0]||(t[0]=[d('<div><h1 id="_07-目标超导搜索策略" tabindex="-1">07 目标超导搜索策略 <a class="header-anchor" href="#_07-目标超导搜索策略" aria-label="Permalink to &quot;07 目标超导搜索策略&quot;">​</a></h1><blockquote><p>CQM 最终实践目标：<strong>常压室温第二类超导体</strong>（$T_c \\ge 300,\\text{K}$，常压，II型）</p></blockquote><hr><h2 id="已有数据资产" tabindex="-1">已有数据资产 <a class="header-anchor" href="#已有数据资产" aria-label="Permalink to &quot;已有数据资产&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">家族</th><th style="text-align:left;">代表材料</th><th style="text-align:left;">$T_c$ 范围</th></tr></thead><tbody><tr><td style="text-align:left;">元素</td><td style="text-align:left;">Nb(9.3K), Pb(7.2K)</td><td style="text-align:left;">0–10K</td></tr><tr><td style="text-align:left;">A15</td><td style="text-align:left;">Nb₃Sn(18K), Nb₃Ge(23K)</td><td style="text-align:left;">17–23K</td></tr><tr><td style="text-align:left;">二元化合物</td><td style="text-align:left;">MgB₂(39K)</td><td style="text-align:left;">39K</td></tr><tr><td style="text-align:left;">铜氧化物</td><td style="text-align:left;">Hg-1223(133K), YBCO(92K)</td><td style="text-align:left;">85–133K</td></tr><tr><td style="text-align:left;">铁基</td><td style="text-align:left;">NdFeAsO(51K), BaFe₂As₂(38K)</td><td style="text-align:left;">8–51K</td></tr><tr><td style="text-align:left;">氢化物</td><td style="text-align:left;">LaH₁₀(250K@170GPa), H₃S(203K@155GPa)</td><td style="text-align:left;">203–250K</td></tr></tbody></table><p>SCDB 46种 + SCData 76元素 + 27化合物基准</p><h2 id="cqm-参数校准" tabindex="-1">CQM 参数校准 <a class="header-anchor" href="#cqm-参数校准" aria-label="Permalink to &quot;CQM 参数校准&quot;">​</a></h2><p><strong>相变判据层级</strong>：丛作用量交叉 $F_1(T_c)=F_2(T_c)$（唯象层）；深层根基为同步算符本征值交叉 $\\lambda_1(T_c)=\\lambda_2(T_c)$（超导同步算符 = 前时空基态紧化结构（GL(5)/SU(5)）重组实现后电磁因子（GL(1)）子结构的再现）。详见 <code>CQM_超导核心理论.md</code> §11.6。</p><p><strong>校准目标</strong>：验证 $T_c = (E_2 - E_1)/(S_2 - S_1)$ 对46种已知超导体的预测能力。</p><p><strong>自由能公式</strong>：$T_c^2 = \\frac{8,\\Delta\\delta_0^2,K_{\\text{eff}},\\theta_D}{9\\ln 2}$（数值验证暂无可复核产物）。</p><h2 id="搜索方向" tabindex="-1">搜索方向 <a class="header-anchor" href="#搜索方向" aria-label="Permalink to &quot;搜索方向&quot;">​</a></h2><ol><li><strong>常压化</strong>：氢化物高压→常压（化学预压缩，Ashcroft 2004）</li><li><strong>高 $N(E_F)$</strong>：平带工程（镍酸盐、魔角石墨烯）</li><li><strong>强耦合</strong>：大 λ（H 声子主导、d/p 波配对）</li><li><strong>CQM 判据</strong>：$\\Delta\\delta_0 \\ge \\frac{☯\\sqrt{1-\\beta\\delta_v}}{2\\beta\\ln n}$（资格条件）</li></ol></div>',1)])])}const h=e(r,[["render",n]]);export{f as __pageData,h as default};
